  ?country2 wdt:[property:instance of] wd:[entity:sovereign state] .
  FILTER(?country1 != ?country2)

  # Not bordering
  FILTER NOT EXISTS { ?country1 wdt:[property:shares border with] ?country2 . }

  # Capitals via statement node with preferred/current
  ?country1 p:[property:capital] ?capStmt1 .
  ?capStmt1 ps:[property:capital] ?capital1 .
  FILTER NOT EXISTS { ?capStmt1 pq:[property:end time] ?endTime1 . }

  ?country2 p:[property:capital] ?capStmt2 .
  ?capStmt2 ps:[property:capital] ?capital2 .
  FILTER NOT EXISTS { ?capStmt2 pq:[property:end time] ?endTime2 . }

  ?capital1 wdt:[property:coordinate location] ?coord1 .
  ?capital2 wdt:[property:coordinate location] ?coord2 .

  BIND(geof:distance(?coord1, ?coord2) AS ?distance)
  FILTER(?distance < 200)
  FILTER(STR(?country1) < STR(?country2))

  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY ?distance

